import {createEndpoint} from "../../../../../server/createEndpoint.js";
import {NextResponse} from "next/server";
import {createUser, getAllUsers, updateUser} from "../../../../../server/features/user/UserSerivce.js";
import Joi from "joi";

export const GET = createEndpoint(async () => {
    const users = await getAllUsers();
    const parsedUsers = users.map((user, index) => {
        const attributes = {}
        user.Attributes.forEach((attribute) => {
            attributes[attribute.Name] = attribute.Value
        })
        return {
            username: user.Username,
            enabled: user.Enabled,
            attributes: attributes
        }
    })
    return NextResponse.json(parsedUsers);
}, null, true, ['admin']);

export const PUT = createEndpoint(async (request, body) => {
    const result = await updateUser(body)

    return NextResponse.json(result);
}, Joi.object({
    username: Joi.string().required(),
    name: Joi.string().optional(),
    email: Joi.string().optional(),
    enabled: Joi.boolean().optional(),
    password: Joi.any().optional()
}), true, ['admin']);

export const POST = createEndpoint(async (request, body) => {
    const {name, email, password} = body;

    const result = await createUser(name, email, password);

    return NextResponse.json(result);
}, Joi.object({
    name: Joi.string().required(),
    email: Joi.string().required(),
    password: Joi.any().required()
}), true, ['admin']);

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import MiddleNav from "@/app/general_components/componentes_recurrentes/MiddleNav";
import { FacturaService } from "@/app/service/FacturaService";

const columns = ["id","invoice_id","record_type","issuer_nif","issuer_name","invoice_series","invoice_number","invoice_date","customer_nif","customer_name","invoice_type","tax_breakdown_json","total_amount","previous_record_id","previous_invoice_number","previous_invoice_date","previous_hash","current_hash","generated_at","aeat_status","aeat_csv","aeat_error_code","aeat_error_description","xml_payload","xml_response","sent_at","accepted_at","software_version","installation_id","created_at"];
const text = (value: unknown) => typeof value === "object" ? JSON.stringify(value) : String(value ?? "");

export default function VerifactuRecordsPage() {
  const [records, setRecords] = useState<any[]>([]);
  const [filters, setFilters] = useState<Record<string, string>>({});
  const [complete, setComplete] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => { FacturaService.getVerifactuRecords().then(v => setRecords(Array.isArray(v) ? v : [])).catch(() => setError("No se pudieron cargar los registros.")); }, []);
  const visibleColumns = complete ? columns : columns.slice(0, 2);
  const filtered = useMemo(() => records.filter(record => visibleColumns.every(column => !filters[column]?.trim() || text(record[column]).toLowerCase().includes(filters[column].trim().toLowerCase()))), [records, filters, complete]);

  return <div className="min-h-screen bg-gray-100 text-gray-700">
    <MiddleNav tituloprincipal="Registros VERI*FACTU" />
    <main className="p-6 lg:p-12">
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3 rounded-xl border border-blue-100 bg-white p-4 shadow-sm">
        <p className="font-medium text-blue-950">Se muestra la tabla en vista {complete ? "completa" : "simplificada"}</p>
        <button type="button" onClick={() => setComplete(value => !value)} className="cursor-pointer rounded bg-blue-950 px-4 py-2 text-sm text-white transition hover:bg-blue-800">
          {complete ? "Pasar a vista simplificada" : "Ampliar a datos completos"}
        </button>
      </div>
      <div className="mb-4 flex justify-end"><Link href="/dashboard/administracion/facturas-clientes" className="cursor-pointer rounded border border-blue-950 px-4 py-2 text-sm text-blue-950 transition hover:bg-blue-50">Volver a facturas</Link></div>
      {error && <p className="mb-4 rounded bg-red-50 p-3 text-red-700">{error}</p>}
      <div className="overflow-x-auto rounded-xl bg-white shadow"><table className="min-w-full text-xs">
        <thead className="bg-blue-950 text-white"><tr>{visibleColumns.map(column => <th key={column} className="p-3 text-left font-medium">{column}</th>)}</tr>
          <tr className="bg-white text-gray-700">{visibleColumns.map(column => <th key={column} className="p-2"><input aria-label={`Filtrar ${column}`} value={filters[column] || ""} onChange={event => setFilters(current => ({...current, [column]: event.target.value}))} className="w-full min-w-40 rounded border border-blue-200 px-2 py-1.5 outline-none transition focus:border-blue-950" placeholder={`Filtrar ${column}`} /></th>)}</tr>
        </thead>
        <tbody>{filtered.map(record => <tr key={record.id} className="border-t transition hover:bg-blue-50">{visibleColumns.map(column => <td key={column} className="max-w-xs truncate p-3" title={text(record[column])}>{text(record[column]) || "—"}</td>)}</tr>)}
          {!filtered.length && !error && <tr><td colSpan={visibleColumns.length} className="p-8 text-center text-gray-500">No hay registros que coincidan con los filtros.</td></tr>}
        </tbody>
      </table></div>
    </main>
  </div>;
}

"use client";
import SearchableSelect from "@/app/components/SearchableSelect";

import { useEffect, useMemo, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import MiddleNav from "@/app/general_components/componentes_recurrentes/MiddleNav";
import { FacturaService } from "@/app/service/FacturaService";
import { ProveedorService } from "@/app/service/ProveedorService";

const formasPago = ["Transferencia", "Recibo", "Tarjeta", "Efectivo", "Confirming"];
const estados = ["Pendiente", "Pagada", "Revisada", "Contabilizada", "Cancelada"];

function splitDate(value = "") {
  const [dd = "", mm = "", yyyy = ""] = String(value).split(/[/-]/);
  return { dd, mm, yyyy };
}

function joinDate(parts: any) {
  return [parts.dd, parts.mm, parts.yyyy].join("/");
}

export default function FacturaProveedorDetallePage() {
  const router = useRouter();
  const params = useParams<{ id_factura_proveedor: string }>();
  const [factura, setFactura] = useState<any | null>(null);
  const [form, setForm] = useState<any>({});
  const [dateParts, setDateParts] = useState<any>({});
  const [proveedores, setProveedores] = useState<any[]>([]);
  const [providerQuery, setProviderQuery] = useState("");
  const [showProviderModal, setShowProviderModal] = useState(false);
  const [pendingProveedor, setPendingProveedor] = useState<any | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!params.id_factura_proveedor) return;
    Promise.all([
      FacturaService.getFacturaProveedorById(params.id_factura_proveedor),
      ProveedorService.getProveedores(),
    ])
      .then(([facturaData, proveedoresData]) => {
        setFactura(facturaData);
        setForm(facturaData);
        setDateParts(splitDate(facturaData.fecha_factura));
        setProveedores(Array.isArray(proveedoresData) ? proveedoresData : []);
      })
      .catch((error) => setError(error?.message || "No se ha podido cargar la factura."))
      .finally(() => setLoading(false));
  }, [params.id_factura_proveedor]);

  const filteredProviders = useMemo(() => {
    const query = providerQuery.trim().toLowerCase();
    return proveedores.filter((proveedor) => !query || Object.values(proveedor).join(" ").toLowerCase().includes(query));
  }, [providerQuery, proveedores]);

  const updateField = (field: string, value: any) => {
    setForm((current: any) => ({ ...current, [field]: value }));
  };

  const updateDate = (field: string, value: string) => {
    const next = { ...dateParts, [field]: value.replace(/\D/g, "") };
    setDateParts(next);
    updateField("fecha_factura", joinDate(next));
  };

  const save = async () => {
    if (Number(form.base_imponible || 0) > Number(form.importe_total || 0)) {
      setError("Base imponible no puede ser mayor al total.");
      return;
    }
    setSaving(true);
    setError("");
    try {
      const updated = await FacturaService.updateFacturaProveedor(factura.id_factura_proveedor, form);
      setFactura(updated);
      setForm(updated);
      setDateParts(splitDate(updated.fecha_factura));
    } catch (error: any) {
      setError(error?.message || "No se ha podido guardar la factura.");
    } finally {
      setSaving(false);
    }
  };

  const remove = async () => {
    if (!window.confirm(`Borrar factura ${factura.id_factura_proveedor}?`)) return;
    await FacturaService.deleteFacturaProveedor(factura.id_factura_proveedor);
    router.push("/dashboard/administracion/facturas-proveedores");
  };

  return (
    <div className="flex min-h-screen w-full flex-col bg-gray-200 text-gray-700">
      <MiddleNav tituloprincipal="Factura proveedor" />
      <div className="min-h-screen w-full bg-gray-100 px-12 py-10">
        <button type="button" onClick={() => router.push("/dashboard/administracion/facturas-proveedores")} className="mb-5 rounded bg-white px-4 py-2 text-sm text-blue-950 shadow-sm hover:bg-gray-50">
          Volver
        </button>
        {loading && <div className="bg-white p-6 text-sm text-gray-500">Cargando factura...</div>}
        {error && <div className="mb-4 border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
        {!loading && factura && (
          <section className="bg-white p-6 shadow-sm">
            <div className="mb-5 flex items-start justify-between gap-4">
              <div>
                <p className="text-xs font-semibold uppercase text-gray-400">ID factura</p>
                <h1 className="text-xl font-semibold text-blue-950">{factura.id_factura_proveedor}</h1>
              </div>
              <div className="flex gap-2">
                <button type="button" onClick={remove} className="rounded bg-red-600 px-4 py-2 text-sm font-medium text-white hover:bg-red-700">Borrar</button>
                <button type="button" onClick={save} disabled={saving} className="rounded bg-blue-950 px-4 py-2 text-sm font-medium text-white hover:bg-blue-900 disabled:bg-gray-400">Guardar</button>
              </div>
            </div>
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
              {["orden_compra_p3", "numero_contabilidad", "codigo_factura", "base_imponible", "importe_total", "comentarios"].map((field) => (
                <label key={field} className="text-sm">
                  <span className="mb-1 block text-xs font-semibold uppercase text-gray-500">{field}</span>
                  <input value={form[field] || ""} onChange={(event) => updateField(field, event.target.value)} className="w-full rounded border px-3 py-2" />
                </label>
              ))}
              <label className="text-sm">
                <span className="mb-1 block text-xs font-semibold uppercase text-gray-500">Forma de pago</span>
                <select value={form.forma_pago || ""} onChange={(event) => updateField("forma_pago", event.target.value)} className="w-full rounded border px-3 py-2">
                  <option value="">Seleccionar</option>
                  {formasPago.map((item) => <option key={item} value={item}>{item}</option>)}
                </select>
              </label>
              <label className="text-sm">
                <span className="mb-1 block text-xs font-semibold uppercase text-gray-500">Estado</span>
                <select value={form.estado || ""} onChange={(event) => updateField("estado", event.target.value)} className="w-full rounded border px-3 py-2">
                  <option value="">Seleccionar</option>
                  {estados.map((item) => <option key={item} value={item}>{item}</option>)}
                </select>
              </label>
              <div>
                <p className="mb-1 text-xs font-semibold uppercase text-gray-500">Fecha factura</p>
                <div className="flex gap-2">
                  <input value={dateParts.dd || ""} onChange={(event) => updateDate("dd", event.target.value.slice(0, 2))} placeholder="dd" className="w-16 rounded border px-2 py-2" />
                  <input value={dateParts.mm || ""} onChange={(event) => updateDate("mm", event.target.value.slice(0, 2))} placeholder="mm" className="w-16 rounded border px-2 py-2" />
                  <input value={dateParts.yyyy || ""} onChange={(event) => updateDate("yyyy", event.target.value.slice(0, 4))} placeholder="yyyy" className="w-24 rounded border px-2 py-2" />
                </div>
              </div>
              <div>
                <p className="mb-1 text-xs font-semibold uppercase text-gray-500">Proveedor</p>
                <button type="button" onClick={() => setShowProviderModal(true)} className="rounded bg-blue-950 px-4 py-2 text-sm font-medium text-white hover:bg-blue-900">
                  {form.id_proveedor ? `Editar proveedor: ${form.proveedor || form.id_proveedor}` : "Seleccionar proveedor"}
                </button>
              </div>
            </div>
          </section>
        )}
      </div>

      {showProviderModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70">
          <div className="w-full max-w-3xl rounded bg-white p-6 shadow-xl">
            <div className="mb-4 flex items-center justify-between">
              <p className="text-lg font-semibold text-blue-950">Seleccionar proveedor</p>
              <button type="button" onClick={() => setShowProviderModal(false)} className="text-xl">x</button>
            </div>
            <SearchableSelect label="Proveedor" required value={pendingProveedor?.id_proveedor||''} onChange={id=>setPendingProveedor(proveedores.find(p=>p.id_proveedor===id)||null)} options={proveedores.map(p=>({value:p.id_proveedor,label:[p.nombre_proveedor,p.id_proveedor,p.vat_code,p.pais_proveedor].filter(Boolean).join(' · ')}))} />
            <div className="mt-5 flex justify-end gap-2">
              <button type="button" onClick={() => setShowProviderModal(false)} className="rounded border px-4 py-2 text-sm">Cancelar</button>
              <button
                type="button"
                disabled={!pendingProveedor}
                onClick={() => {
                  setForm({ ...form, id_proveedor: pendingProveedor.id_proveedor, proveedor: pendingProveedor.nombre_proveedor });
                  setShowProviderModal(false);
                  setPendingProveedor(null);
                }}
                className="rounded bg-blue-950 px-4 py-2 text-sm font-medium text-white disabled:bg-gray-400"
              >
                Confirmar
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";
import SearchableSelect from "@/app/components/SearchableSelect";
import {useEffect,useMemo,useState} from "react";import {useRouter} from "next/navigation";import MiddleNav from "@/app/general_components/componentes_recurrentes/MiddleNav";
type Payment={forma:string;day:string;month:string;year:string;importe:string};
const empty=():Payment=>({forma:"",day:"",month:"",year:"",importe:""});const date=(p:Payment)=>`${p.day.padStart(2,"0")}/${p.month.padStart(2,"0")}/${p.year}`;
export default function AgregarFacturaProveedor(){
 const router=useRouter();const [phase,setPhase]=useState(1),[providers,setProviders]=useState<any[]>([]),[provider,setProvider]=useState<any>(null),[search,setSearch]=useState(""),[file,setFile]=useState<File|null>(null),[payments,setPayments]=useState<Payment[]>([empty()]),[confirm,setConfirm]=useState<number|null>(null),[error,setError]=useState(""),[saving,setSaving]=useState(false);
 const now=new Date(),[form,setForm]=useState({number:"",day:String(now.getDate()),month:String(now.getMonth()+1),year:String(now.getFullYear()),base:"",total:"",comments:""});
 useEffect(()=>{fetch("/api/v1/admin/proveedores").then(r=>r.json()).then(data=>{setProviders(data);const id=new URLSearchParams(window.location.search).get('id_proveedor');if(id)setProvider(data.find((p:any)=>p.id_proveedor===id)||null);})},[]);useEffect(()=>{const x=(e:KeyboardEvent)=>{if(e.key==="Escape")setConfirm(null)};addEventListener("keydown",x);return()=>removeEventListener("keydown",x)},[]);
 const sum=payments.reduce((s,p)=>s+Number(p.importe||0),0),diff=sum-Number(form.total||0),complete=payments.every(p=>p.forma&&p.day&&p.month&&p.year&&p.importe!=="");
 function next(){setError("");if(phase===1&&!provider)return setError("Selecciona un proveedor.");if(phase===2&&(!file||!form.number||!form.day||!form.month||!form.year||form.base===""||form.total===""))return setError("Completa todos los datos y adjunta el PDF.");if(phase===3&&(!complete||Math.abs(diff)>.005))return setError("Completa los pagos y haz que cuadren exactamente con el total.");setPhase(p=>p+1)}
 async function save(){setSaving(true);try{const pre=await fetch("/api/v1/mediateca/media/presign",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({filename:file!.name,contentType:file!.type||"application/pdf",prefix:"facturas_proveedores"})}).then(async r=>{if(!r.ok)throw new Error((await r.json()).message);return r.json()});const up=await fetch(pre.uploadUrl,{method:"PUT",headers:{"Content-Type":file!.type||"application/pdf"},body:file});if(!up.ok)throw new Error("Error al subir el PDF");const res=await fetch("/api/v1/admin/facturas-proveedores",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id_proveedor:provider.id_proveedor,numero_factura_proveedor:form.number,fecha_factura:`${form.day.padStart(2,"0")}/${form.month.padStart(2,"0")}/${form.year}`,base_imponible:form.base,importe_total:form.total,documento_src:pre.cdnUrl,comentarios:form.comments,pagos:payments.map(p=>({forma:p.forma,fecha:date(p),importe:p.importe}))})});if(!res.ok)throw new Error((await res.json()).message);router.push("/dashboard/administracion/facturas-proveedores")}catch(e:any){setError(e.message);setSaving(false)}}
 const matches=useMemo(()=>providers.filter(p=>`${p.id_proveedor} ${p.nombre_proveedor}`.toLowerCase().includes(search.toLowerCase())),[providers,search]);
 return <div className="min-h-screen bg-gray-100"><MiddleNav tituloprincipal="Agregar factura de proveedor"/><main className="mx-auto max-w-4xl p-6 lg:p-12"><div className="mb-6 flex gap-2">{[1,2,3,4].map(n=><div key={n} className={`flex-1 rounded p-2 text-center text-sm ${phase===n?"bg-blue-950 text-white":"bg-white"}`}>Fase {n}</div>)}</div><section className="rounded-xl bg-white p-6 shadow">
 {phase===1&&<><h2 className="mb-4 text-xl font-semibold">Selecciona un proveedor</h2><SearchableSelect label="Proveedor" required value={provider?.id_proveedor||''} onChange={value=>setProvider(providers.find(p=>p.id_proveedor===value)||null)} options={providers.map(p=>({value:p.id_proveedor,label:p.nombre_proveedor+' · '+p.id_proveedor}))} /></>}
 {phase===2&&<><h2 className="mb-4 text-xl font-semibold">Datos de la factura</h2><div className="grid gap-4 sm:grid-cols-2"><label>Número del proveedor<input value={form.number} onChange={e=>setForm({...form,number:e.target.value})} className="mt-1 w-full rounded border p-2"/></label><label>PDF<input type="file" accept="application/pdf" onChange={e=>setFile(e.target.files?.[0]||null)} className="mt-1 w-full cursor-pointer rounded border p-2 file:cursor-pointer"/></label><fieldset><legend>Fecha</legend><div className="flex gap-1">{([["day","dd",2],["month","mm",2],["year","yyyy",4]] as const).map(([k,p,n])=><input key={k} maxLength={n} placeholder={p} value={(form as any)[k]} onChange={e=>setForm({...form,[k]:e.target.value.replace(/\D/g,"")})} className="min-w-0 flex-1 rounded border p-2"/>)}</div></fieldset><label>Base imponible<input type="number" step=".01" value={form.base} onChange={e=>setForm({...form,base:e.target.value})} className="mt-1 w-full rounded border p-2"/></label><label>Total<input type="number" step=".01" value={form.total} onChange={e=>setForm({...form,total:e.target.value})} className="mt-1 w-full rounded border p-2"/></label></div></>}
 {phase===3&&<><div className="mb-4 flex items-center justify-between"><div><h2 className="text-xl font-semibold">Pagos</h2><p className={`text-sm ${Math.abs(diff)<.005&&complete?"text-green-700":"text-red-700"}`}>{Math.abs(diff)<.005&&complete?"Los pagos cuadran con el total":`Descuadre ${diff>=0?"+":"-"} ${Math.abs(diff).toFixed(2)} €`}</p></div><button type="button" aria-label="Añadir pago" onClick={()=>setPayments([...payments,empty()])} className="h-10 w-10 cursor-pointer rounded-full bg-blue-950 text-2xl text-white transition hover:bg-blue-800">+</button></div><div className="space-y-3">{payments.map((p,i)=><div key={i} className="grid gap-2 rounded border p-4 sm:grid-cols-[1fr_2fr_1fr_auto]"><input placeholder="Forma" value={p.forma} onChange={e=>setPayments(payments.map((x,j)=>j===i?{...x,forma:e.target.value}:x))} className="rounded border p-2"/><div className="flex gap-1">{([["day","dd",2],["month","mm",2],["year","yyyy",4]] as const).map(([k,ph,n])=><input key={k} maxLength={n} placeholder={ph} value={(p as any)[k]} onChange={e=>setPayments(payments.map((x,j)=>j===i?{...x,[k]:e.target.value.replace(/\D/g,"")}:x))} className="min-w-0 flex-1 rounded border p-2"/>)}</div><input type="number" step=".01" placeholder="Importe" value={p.importe} onChange={e=>setPayments(payments.map((x,j)=>j===i?{...x,importe:e.target.value}:x))} className="rounded border p-2"/><button type="button" onClick={()=>setConfirm(i)} className="cursor-pointer rounded px-3 text-red-700 transition hover:bg-red-50">Eliminar</button></div>)}</div></>}
 {phase===4&&<><h2 className="text-xl font-semibold">Revisión final</h2><div className="my-4 rounded bg-blue-50 p-4"><p><b>Proveedor:</b> {provider.nombre_proveedor}</p><p><b>Factura:</b> {form.number}</p><p><b>Total:</b> {Number(form.total).toFixed(2)} €</p><p><b>Pagos:</b> {payments.length}</p></div><label>Comentarios<textarea value={form.comments} onChange={e=>setForm({...form,comments:e.target.value})} rows={5} className="mt-1 w-full rounded border p-2"/></label></>}
 {error&&<p className="mt-4 rounded bg-red-50 p-3 text-red-700">{error}</p>}<div className="mt-6 flex justify-between"><button type="button" disabled={phase===1} onClick={()=>setPhase(p=>p-1)} className="cursor-pointer rounded border px-4 py-2 transition hover:bg-gray-100 disabled:cursor-not-allowed disabled:opacity-40">Anterior</button>{phase<4?<button type="button" onClick={next} className="cursor-pointer rounded bg-blue-950 px-5 py-2 text-white transition hover:bg-blue-800">Siguiente</button>:<button type="button" disabled={saving} onClick={save} className="cursor-pointer rounded bg-blue-950 px-5 py-2 text-white transition hover:bg-blue-800 disabled:cursor-not-allowed disabled:opacity-50">{saving?"Guardando...":"Crear factura"}</button>}</div></section></main>
 {confirm!==null&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4"><div role="dialog" className="relative w-full max-w-sm rounded-xl bg-white p-6"><button type="button" aria-label="Cerrar" onClick={()=>setConfirm(null)} className="absolute right-3 top-2 cursor-pointer text-3xl hover:text-blue-700">×</button><h3 className="text-lg font-semibold">¿Eliminar este pago?</h3><div className="mt-5 flex justify-end gap-2"><button type="button" onClick={()=>setConfirm(null)} className="cursor-pointer rounded border px-4 py-2 hover:bg-gray-100">Cancelar</button><button type="button" onClick={()=>{setPayments(payments.filter((_,i)=>i!==confirm));setConfirm(null)}} className="cursor-pointer rounded bg-red-700 px-4 py-2 text-white hover:bg-red-800">Eliminar</button></div></div></div>}
 </div>
}

import { InterfazContacto } from '@/app/interfaces/interfaces';
import React, { FC, ChangeEvent } from 'react';
 
interface DatosGralesContactoProps {
  contacto: InterfazContacto;
  setContactoEditable: React.Dispatch<React.SetStateAction<InterfazContacto | undefined>>;
  onChange: () => void;
}

const DatosGralesContacto: FC<DatosGralesContactoProps> = ({ contacto, setContactoEditable, onChange }) => {
  const handleChange = (field: keyof InterfazContacto, value: string) => {
    setContactoEditable(prev => {
      if (!prev) return prev;
      const updated = { ...prev, [field]: value };
      // Actualizar nombre_completo_contacto si cambia nombre o apellidos
      if (field === 'nombre_contacto' || field === 'apellidos_contacto') {
        updated.nombre_completo_contacto = `${updated.nombre_contacto} ${updated.apellidos_contacto}`;
      }
      return updated;
    });
    onChange();
  };

  return (
    <div className="p-4">
      <h2 className="text-xl font-bold mb-4">Datos generales del contacto</h2>
      <table className="min-w-full">
        <thead className="bg-blue-950/80 text-white">
          <tr>
            <th className="text-left p-2 font-light">Nombre del contacto</th>
            <th className="text-left p-2 font-light">Apellidos del contacto</th>
            <th className="text-left p-2 font-light">Id del contacto</th>
            <th className="text-left p-2 font-light">Teléfono principal</th>
            <th className="text-left p-2 font-light">Email principal</th>
          </tr>
        </thead>
        <tbody>
          <tr className="border-t border-gray-200 hover:bg-gray-100/30">
            <td className="p-2 border-b border-gray-200">
              <input
                type="text"
                value={contacto.nombre_contacto}
                onChange={(e) => handleChange('nombre_contacto', e.target.value)}
                className="w-full border border-gray-200 rounded p-1"
              />
            </td>
            <td className="p-2 border-b border-gray-200">
              <input
                type="text"
                value={contacto.apellidos_contacto}
                onChange={(e) => handleChange('apellidos_contacto', e.target.value)}
                className="w-full border border-gray-200 rounded p-1"
              />
            </td>
            <td className="p-2 border-b border-gray-200">{contacto.id_contacto}</td>
            <td className="p-2 border-b border-gray-200">
              <input
                type="text"
                value={contacto.telefono_contacto}
                onChange={(e) => handleChange('telefono_contacto', e.target.value)}
                className="w-full border border-gray-200 rounded p-1"
              />
            </td>
            <td className="p-2 border-b border-gray-200">
              <input
                type="email"
                value={contacto.email_contacto}
                onChange={(e) => handleChange('email_contacto', e.target.value)}
                className="w-full border border-gray-200 rounded p-1"
              />
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};

export default DatosGralesContacto;

import { InterfazContacto } from "@/app/interfaces/interfaces";
import React, { FC } from "react";
import CountrySelect from "@/app/components/CountrySelect";
 
interface OtrosDatosContactoProps {
  contacto: InterfazContacto;
  setContactoEditable: React.Dispatch<React.SetStateAction<InterfazContacto | undefined>>;
  suscripciones: string[];
  setSuscripciones: React.Dispatch<React.SetStateAction<string[]>>;
  otrosDatos: string;
  setOtrosDatos: React.Dispatch<React.SetStateAction<string>>;
  idiomas: string;
  setIdiomas: React.Dispatch<React.SetStateAction<string>>;
  pais: string;
  setPais: React.Dispatch<React.SetStateAction<string>>;
  conocidoEn: string;
  setConocidoEn: React.Dispatch<React.SetStateAction<string>>;
  contactadoEnFeria: string;
  setContactadoEnFeria: React.Dispatch<React.SetStateAction<string>>;
  onChange: () => void;
}

const OtrosDatosContacto: FC<OtrosDatosContactoProps> = ({ 
  contacto,
  setContactoEditable,
  suscripciones,
  setSuscripciones,
  otrosDatos,
  setOtrosDatos,
  idiomas,
  setIdiomas,
  pais,
  setPais,
  conocidoEn,
  setConocidoEn,
  contactadoEnFeria,
  setContactadoEnFeria,
  onChange
}) => {

  const opcionesSuscripciones = [
    "Newsletter Vidrio España",
    "Newsletter Vidrio Latam",
    "Revista del Vidrio España",
    "Revista del vidrio Latam",
    "QQ Vidrio España",
    "Newsletter Ventanas España",
    "Newsletter Ventanas Latam",
    "Revista Ventanas España",
    "Revista Ventanas Latam",
    "QQ Ventanas España",
    "Newsletter Proteccion Solar España",
    "Newsletter Proteccion Solar Latam",
    "Newsletter Puertas España",
    "Newsletter Puertas Latam",
    "Newsletter Arquitectura",
    "Revista Hueco Arquitectura",
  ];

  const toggleSuscripcion = (opcion: string) => {
    const nuevasSuscripciones = suscripciones.includes(opcion)
      ? suscripciones.filter((s) => s !== opcion)
      : [...suscripciones, opcion];

    setSuscripciones(nuevasSuscripciones);
    setContactoEditable(prev => 
      prev ? { ...prev, suscripciones: nuevasSuscripciones } : prev
    );
    onChange();
  };

  const handleOtrosDatosChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const value = e.target.value;
    setOtrosDatos(value);
    setContactoEditable(prev => 
      prev ? { ...prev, otros_datos_interes: value } : prev
    );
    onChange();
  };

  const handleIdiomasChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setIdiomas(value);
    setContactoEditable(prev => 
      prev ? { ...prev, idiomas: value } : prev
    );
    onChange();
  };

  const handlePaisChange = (value: string) => {
    setPais(value);
    setContactoEditable(prev => 
      prev ? { ...prev, pais_contacto: value } : prev
    );
    onChange();
  };

  const handleConocidoEnChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setConocidoEn(value);
    setContactoEditable(prev => 
      prev ? { ...prev, conocido_en: value } : prev
    );
    onChange();
  };

  const handleContactadoEnFeriaChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    setContactadoEnFeria(value);
    setContactoEditable(prev => 
      prev ? { ...prev, contactado_en_feria: value } : prev
    );
    onChange();
  };

  return (
    <div className="p-4">
      <h2 className="text-xl font-bold mb-4">Otros datos del contacto</h2>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
         <div className="flex flex-col gap-4">
          <div className="flex items-center gap-4">
            <label className="w-1/3 text-gray-700">País</label>
            <CountrySelect
              value={pais}
              onChange={handlePaisChange}
              className="flex-1 border border-gray-300 rounded-lg p-2 text-gray-700"
            />
          </div>

          <div className="flex items-center gap-4">
            <label className="w-1/3 text-gray-700">Idiomas</label>
            <input
              type="text"
              value={idiomas}
              onChange={handleIdiomasChange}
              className="flex-1 border border-gray-300 rounded-lg p-2 text-gray-700"
              placeholder="Ej: Español, Inglés"
            />
          </div>

          <div className="flex items-center gap-4">
            <label className="w-1/3 text-gray-700">Conocido en</label>
            <input
              type="text"
              value={conocidoEn}
              onChange={handleConocidoEnChange}
              className="flex-1 border border-gray-300 rounded-lg p-2 text-gray-700"
              placeholder="Ej: Feria, Referencia..."
            />
          </div>

          <div className="flex items-center gap-4">
            <label className="w-1/3 text-gray-700">Contactado en feria</label>
            <input
              type="text"
              value={contactadoEnFeria}
              onChange={handleContactadoEnFeriaChange}
              className="flex-1 border border-gray-300 rounded-lg p-2 text-gray-700"
              placeholder="Ej: Veteco, Glasstech..."
            />
          </div>
        </div>

         <div>
          <label className="block text-gray-700 mb-2 font-medium">Suscripciones</label>
          <div className="grid grid-cols-2 gap-2">
            {opcionesSuscripciones.map((opcion, idx) => (
              <label key={idx} className="flex items-center gap-2 text-gray-700">
                <input
                  type="checkbox"
                  checked={suscripciones.includes(opcion)}
                  onChange={() => toggleSuscripcion(opcion)}
                  className="h-4 w-4 border-gray-300 rounded"
                />
                {opcion}
              </label>
            ))}
          </div>
        </div>
      </div>

       <h2 className="text-xl font-bold mb-4 mt-6">Otros datos de interés</h2>
      <textarea
        className="border border-gray-300 rounded-lg w-full p-2 text-gray-700"
        placeholder="Introduzca aquí otros datos de interés"
        value={otrosDatos}
        onChange={handleOtrosDatosChange}
        rows={4}
      />
    </div>
  );
};

export default OtrosDatosContacto;

import SearchableSelect from "@/app/components/SearchableSelect";
import { InterfazCuenta } from "@/app/interfaces/interfaces";
import React, { useEffect, useState } from "react";



interface PopupEmpresaProps {
  isOpen: boolean;
  onClose: () => void;
  empresas: InterfazCuenta[];
  onSelect: (empresa: InterfazCuenta) => void;
}

const PopupEmpresa: React.FC<PopupEmpresaProps> = ({
  isOpen,
  onClose,
  empresas,
  onSelect,
}) => {
  const [busquedaNombre, setBusquedaNombre] = useState("");
  const [busquedaCodigo, setBusquedaCodigo] = useState("");
  const [resultados, setResultados] = useState<InterfazCuenta[] | null>(null);
  const [cargando, setCargando] = useState(false);

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", handleEsc);
    return () => document.removeEventListener("keydown", handleEsc);
  }, [onClose]);

  const handleBuscar = () => {
    setCargando(true);
    setResultados(null);
    setTimeout(() => {
      const coincidencias = empresas.filter(
        (e) =>
          e.nombre_empresa.toLowerCase().includes(busquedaNombre.toLowerCase()) ||
          e.id_cuenta.toLowerCase().includes(busquedaCodigo.toLowerCase())
      );
      setResultados(coincidencias);
      setCargando(false);
    }, 3000);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50">
      <div className="bg-white rounded-2xl shadow-lg p-6 w-[700px] relative">
        <button
          onClick={onClose}
          className="absolute top-3 right-3 text-gray-500 hover:text-gray-800"
        >
          ×
        </button>

        <h2 className="text-xl font-bold mb-4">Buscar empresa</h2>

        <SearchableSelect label="Empresa" value="" onChange={id=>{const item=empresas.find(r=>r.id_cuenta===id);if(item){onSelect(item);onClose();}}} options={empresas.map(r=>({value:r.id_cuenta,label:[r.nombre_empresa,r.id_cuenta,r.pais_cuenta].filter(Boolean).join(' · ')}))} />
      </div>
    </div>
  );
};

export default PopupEmpresa;

"use client";
import SearchableSelect from "@/app/components/SearchableSelect";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { Search, X } from "lucide-react";
import MiddleNav from "@/app/general_components/componentes_recurrentes/MiddleNav";
import { ContactoService } from "@/app/service/ContactoService";
import { CuentaService } from "@/app/service/CuentaService";
import paises from "@/app/data/paises.json";

type Cuenta = {
  id_cuenta: string;
  nombre_empresa: string;
  pais_cuenta: string;
  cif?: string;
  vat_code?: string;
  correo_principal?: string;
};

type ContactForm = {
  id_contacto: string;
  id_cuenta: string;
  nombre_empresa: string;
  nombre_contacto: string;
  apellidos_contacto: string;
  email_contacto: string;
  telefono_contacto: string;
  cargo_contacto: string;
  linkedin_cuenta: string;
  url_contacto: string;
  pais_contacto: string;
};

const initialForm = (): ContactForm => ({
  id_contacto: `cont_${Date.now().toString(36)}`,
  id_cuenta: "",
  nombre_empresa: "",
  nombre_contacto: "",
  apellidos_contacto: "",
  email_contacto: "",
  telefono_contacto: "",
  cargo_contacto: "",
  linkedin_cuenta: "",
  url_contacto: "",
  pais_contacto: "",
});

function emailValido(value: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

export default function CrearContacto() {
  const router = useRouter();
  const [step, setStep] = useState(1);
  const [form, setForm] = useState<ContactForm>(() => initialForm());
  const [linked, setLinked] = useState(false);
  const [cuentas, setCuentas] = useState<Cuenta[]>([]);
  const [accountModalOpen, setAccountModalOpen] = useState(false);
  const [paisQuery, setPaisQuery] = useState("");
  const [paisOpen, setPaisOpen] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    CuentaService.getCuentas()
      .then((data) => setCuentas(Array.isArray(data) ? data : []))
      .catch(() => setCuentas([]));
  }, []);

  const update = (patch: Partial<ContactForm>) => setForm((current) => ({ ...current, ...patch }));
  const selectedAccount = cuentas.find((cuenta) => cuenta.id_cuenta === form.id_cuenta);
  const requiredValid = Boolean(form.nombre_contacto.trim() && form.email_contacto.trim() && emailValido(form.email_contacto));
  const filteredCountries = useMemo(() => {
    const term = paisQuery.trim().toLowerCase();
    return (paises as string[]).filter((pais) => !term || pais.toLowerCase().includes(term)).slice(0, 12);
  }, [paisQuery]);

  const next = () => {
    if (step === 1 && linked && !form.id_cuenta) return;
    if (step === 2 && !requiredValid) return;
    setStep((current) => Math.min(4, current + 1));
  };

  const createContacto = async () => {
    try {
      setSubmitting(true);
      setError("");
      const created = await ContactoService.createContacto({
        id_contacto: form.id_contacto,
        id_cuenta: linked ? form.id_cuenta : "",
        nombre_empresa: linked ? form.nombre_empresa : "",
        nombre_contacto: form.nombre_contacto.trim(),
        apellidos_contacto: form.apellidos_contacto.trim(),
        nombre_completo_contacto: `${form.nombre_contacto} ${form.apellidos_contacto}`.trim(),
        email_contacto: form.email_contacto.trim(),
        telefono_contacto: form.telefono_contacto.trim(),
        cargo_contacto: form.cargo_contacto.trim(),
        linkedin_cuenta: form.linkedin_cuenta.trim(),
        url_contacto: form.url_contacto.trim(),
        pais_contacto: form.pais_contacto.trim(),
      });
      router.push(`/dashboard/comercial/contactos/${created.id_contacto || form.id_contacto}`);
    } catch (error: any) {
      setError(error?.response?.data?.message || error?.message || "No se ha podido crear el contacto.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-white text-slate-700">
      <MiddleNav tituloprincipal="Crear contacto" />
      <main className="px-8 py-8">
        <StepHeader current={step} labels={["Vincular cuenta", "Datos obligatorios", "Datos opcionales", "Preview"]} />
        <div className="mt-8 rounded-lg border border-slate-200 bg-white p-8 shadow-sm">
          {error && <div className="mb-5 rounded border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}

          {step === 1 && (
            <section className="space-y-6">
              <div>
                <h2 className="text-lg font-bold text-slate-800">¿Este contacto va a estar asociado a una cuenta?</h2>
                <div className="mt-4 flex items-center gap-4">
                  <Toggle checked={linked} onChange={(value) => {
                    setLinked(value);
                    if (!value) update({ id_cuenta: "", nombre_empresa: "" });
                  }} />
                  <span className="text-lg font-medium">{linked ? "Si" : "No"}</span>
                </div>
              </div>

              {linked && (
                <div>
                  <label className="mb-2 block text-sm font-semibold text-slate-700">Cuenta asociada <span className="text-red-600">*</span></label>
                  <button
                    type="button"
                    onClick={() => setAccountModalOpen(true)}
                    className="flex min-h-14 w-full items-center justify-center rounded-lg border border-dashed border-slate-300 px-4 text-center font-semibold text-slate-700 hover:border-blue-600 hover:bg-blue-50"
                  >
                    {selectedAccount ? `${selectedAccount.nombre_empresa} (${selectedAccount.id_cuenta})` : "Seleccionar cuenta"}
                  </button>
                </div>
              )}
            </section>
          )}

          {step === 2 && (
            <section className="space-y-5">
              <h2 className="text-lg font-bold text-slate-800">Datos obligatorios</h2>
              <TextField label="ID contacto (solo lectura)" value={form.id_contacto} readOnly />
              {linked && <TextField label="ID cuenta (solo lectura)" value={form.id_cuenta} readOnly />}
              <TextField label="Nombre" required value={form.nombre_contacto} onChange={(value) => update({ nombre_contacto: value })} placeholder="Nombre" />
              <TextField label="Apellidos" value={form.apellidos_contacto} onChange={(value) => update({ apellidos_contacto: value })} placeholder="Apellidos" />
              <TextField label="Cargo" value={form.cargo_contacto} onChange={(value) => update({ cargo_contacto: value })} placeholder="Director comercial" />
              <TextField label="Email" required value={form.email_contacto} onChange={(value) => update({ email_contacto: value })} placeholder="email@empresa.com" />
              {form.email_contacto && !emailValido(form.email_contacto) && <p className="text-sm text-red-600">El email debe tener formato nombre@dominio.ext.</p>}
              <TextField label="Telefono" value={form.telefono_contacto} onChange={(value) => update({ telefono_contacto: value })} placeholder="+34 900 000 000" />
              {linked && <TextField label="Cuenta vinculada" value={form.nombre_empresa} readOnly />}
            </section>
          )}

          {step === 3 && (
            <section className="space-y-5">
              <div className="flex items-start justify-between gap-4">
                <div>
                  <h2 className="text-lg font-bold text-slate-800">Datos opcionales</h2>
                  <p className="mt-1 text-sm text-slate-500">Puedes completarlos ahora o editar la ficha mas adelante.</p>
                </div>
                <button type="button" onClick={() => setStep(4)} className="rounded-lg border border-blue-950 px-4 py-2 text-sm font-semibold text-blue-950 hover:bg-blue-50">Saltar fase</button>
              </div>
              <TextField label="Cuenta de LinkedIn" value={form.linkedin_cuenta} onChange={(value) => update({ linkedin_cuenta: value })} placeholder="@persona" />
              <TextField label="URL" value={form.url_contacto} onChange={(value) => update({ url_contacto: value })} placeholder="https://www.linkedin.com/in/..." />
              <CountryField
                value={form.pais_contacto}
                query={paisQuery}
                open={paisOpen}
                options={filteredCountries}
                onFocus={() => {
                  setPaisOpen(true);
                  setPaisQuery(form.pais_contacto);
                }}
                onQueryChange={(value) => {
                  setPaisQuery(value);
                  update({ pais_contacto: "" });
                  setPaisOpen(true);
                }}
                onSelect={(pais) => {
                  update({ pais_contacto: pais });
                  setPaisQuery(pais);
                  setPaisOpen(false);
                }}
              />
            </section>
          )}

          {step === 4 && (
            <section className="space-y-5">
              <h2 className="text-lg font-bold text-slate-800">Preview</h2>
              <div className="grid gap-3 text-sm md:grid-cols-2">
                <Preview label="ID contacto" value={form.id_contacto} />
                <Preview label="Cuenta" value={linked ? `${form.nombre_empresa} (${form.id_cuenta})` : "No asociada"} />
                <Preview label="Nombre" value={`${form.nombre_contacto} ${form.apellidos_contacto}`.trim()} />
                <Preview label="Cargo" value={form.cargo_contacto} />
                <Preview label="Email" value={form.email_contacto} />
                <Preview label="Telefono" value={form.telefono_contacto} />
                <Preview label="LinkedIn" value={form.linkedin_cuenta} />
                <Preview label="URL" value={form.url_contacto} />
                <Preview label="Pais" value={form.pais_contacto} />
              </div>
            </section>
          )}

          <div className="mt-8 flex items-center justify-between gap-3">
            <button type="button" disabled={step === 1 || submitting} onClick={() => setStep((current) => Math.max(1, current - 1))} className="rounded-lg bg-slate-200 px-5 py-2 text-sm font-semibold text-slate-700 hover:bg-slate-300 disabled:cursor-not-allowed disabled:bg-slate-100 disabled:text-slate-400">Atras</button>
            {step < 4 ? (
              <button type="button" disabled={(step === 1 && linked && !form.id_cuenta) || (step === 2 && !requiredValid)} onClick={next} className="rounded-lg bg-blue-600 px-5 py-2 text-sm font-semibold text-white hover:bg-blue-700 disabled:cursor-not-allowed disabled:bg-slate-300">
                Siguiente
              </button>
            ) : (
              <button type="button" disabled={submitting} onClick={createContacto} className="rounded-lg bg-blue-950 px-5 py-2 text-sm font-semibold text-white hover:bg-blue-900 disabled:cursor-not-allowed disabled:bg-slate-300">
                {submitting ? "Creando..." : "Crear contacto"}
              </button>
            )}
          </div>
        </div>
      </main>

      {accountModalOpen && (
        <AccountModal
          cuentas={cuentas}
          selectedId={form.id_cuenta}
          onClose={() => setAccountModalOpen(false)}
          onSelect={(cuenta) => {
            update({ id_cuenta: cuenta.id_cuenta, nombre_empresa: cuenta.nombre_empresa });
            setAccountModalOpen(false);
          }}
        />
      )}
    </div>
  );
}

function StepHeader({ current, labels }: { current: number; labels: string[] }) {
  return (
    <div className="border-b border-slate-200 bg-slate-50 px-6 py-5">
      <div className="flex flex-wrap items-center gap-7">
        {[1, 2, 3, 4].map((step, index) => (
          <div key={step} className="flex items-center gap-7">
            <div className={`flex h-12 w-12 items-center justify-center rounded-full text-lg font-bold ${step === current ? "bg-blue-600 text-white" : step < current ? "bg-green-100 text-green-700" : "bg-slate-200 text-slate-500"}`}>
              {step}
            </div>
            {index < 3 && <div className="h-1 w-10 bg-slate-300" />}
            {step === current && <span className="hidden text-sm font-semibold text-slate-600 md:inline">{labels[index]}</span>}
          </div>
        ))}
      </div>
    </div>
  );
}

function Toggle({ checked, onChange }: { checked: boolean; onChange: (value: boolean) => void }) {
  return (
    <button
      type="button"
      aria-pressed={checked}
      onClick={() => onChange(!checked)}
      className={`relative h-9 w-20 rounded-full p-1 transition ${checked ? "bg-blue-600" : "bg-slate-200"}`}
    >
      <span className={`block h-7 w-7 rounded-full bg-white shadow transition ${checked ? "translate-x-11" : "translate-x-0"}`} />
    </button>
  );
}

function TextField({ label, value, onChange, placeholder = "", required = false, readOnly = false }: { label: string; value: string; onChange?: (value: string) => void; placeholder?: string; required?: boolean; readOnly?: boolean }) {
  return (
    <label className="block text-sm">
