"use client";
import SearchableSelect from "@/app/components/SearchableSelect";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import MiddleNav from "@/app/general_components/componentes_recurrentes/MiddleNav";

type Tab = "registrados" | "pendientes";
const emptyExpense = { id_proveedor: "", id_factura_proveedor: "", day: "", month: "", year: "", bi_pago: "", total_pago: "", forma_pago: "recibo", cuenta_pago: "Sabadell", nombre_planificacion: "", descripcion_planificacion: "", comentarios: "" };

export default function PrevisionGastosPage() {
  const router = useRouter();
  const [rows, setRows] = useState<any[]>([]);
  const [providers, setProviders] = useState<any[]>([]);
  const [filter, setFilter] = useState("");
  const [tab, setTab] = useState<Tab>("registrados");
  const [showModal, setShowModal] = useState(false);
  const [reloadKey, setReloadKey] = useState(0);
  useEffect(() => { Promise.all([fetch("/api/v1/direccion/prevision-gastos").then((r) => r.json()), fetch("/api/v1/admin/proveedores").then((r) => r.json())]).then(([payments, providerRows]) => { setRows(Array.isArray(payments) ? payments : []); setProviders(Array.isArray(providerRows) ? providerRows : []); }); }, [reloadKey]);
  const shown = useMemo(() => rows.filter((row) => tab === "registrados" ? Boolean(row.id_proveedor) : !row.id_proveedor).filter((row) => !filter.trim() || Object.values(row).join(" ").toLowerCase().includes(filter.trim().toLowerCase())), [filter, rows, tab]);
  return <div className="min-h-screen bg-gray-100"><MiddleNav tituloprincipal="Previsión gastos"/><main className="p-6 lg:p-12">
    <div className="mb-4 flex flex-col gap-3 xl:flex-row xl:items-end xl:justify-between"><div><div className="flex gap-2">{([{ key: "registrados", label: "Gastos previstos registrados" }, { key: "pendientes", label: "Gastos pendientes de asociar" }] as const).map((item) => <button key={item.key} type="button" onClick={() => setTab(item.key)} className={`cursor-pointer rounded px-4 py-2 text-sm transition hover:shadow-sm ${tab === item.key ? "bg-blue-950 text-white" : "bg-white hover:bg-gray-200"}`}>{item.label}</button>)}</div><p className="mt-2 text-sm text-gray-500">Cada vencimiento o pago se registra como un gasto independiente.</p></div><div className="flex flex-col gap-2 sm:flex-row"><label className="text-sm font-medium">Filtrar gastos<input type="search" placeholder="Proveedor, factura, fecha, banco..." value={filter} onChange={(event) => setFilter(event.target.value)} className="mt-1 block w-full rounded border border-gray-300 bg-white px-3 py-2 outline-none transition focus:border-blue-950 sm:w-96"/></label>{tab === "registrados" && <button type="button" onClick={() => setShowModal(true)} className="mt-auto cursor-pointer rounded bg-blue-950 px-4 py-2 text-sm font-semibold text-white transition hover:bg-blue-900 hover:shadow-md">Agregar gasto previsto</button>}</div></div>
    <div className="overflow-x-auto bg-white shadow-sm"><table className="min-w-full text-sm"><thead className="bg-blue-950 text-white"><tr>{["Pago","Proveedor","Fecha","Forma","Banco","Base imponible","Importe","Descripción"].map((label) => <th key={label} className="p-3 text-left font-medium">{label}</th>)}</tr></thead><tbody>{shown.map((row) => <tr key={row.id_pago} onClick={() => router.push(`/dashboard/direccion/previsiones/prevision-gastos/${encodeURIComponent(row.id_pago)}`)} className="cursor-pointer border-b transition hover:bg-blue-50"><td className="p-3 font-medium text-blue-950">{row.id_pago}</td><td className="p-3">{row.nombre_proveedor || row.id_proveedor || <span className="text-amber-700">Pendiente de asociar</span>}</td><td className="p-3">{row.fecha_pago || "-"}</td><td className="p-3 capitalize">{row.forma_pago || "-"}</td><td className="p-3">{row.cuenta_pago || "-"}</td><td className="p-3">{Number(row.bi_pago || 0).toFixed(2)} €</td><td className="p-3">{Number(row.total_pago || 0).toFixed(2)} €</td><td className="p-3">{row.descripcion_planificacion || "—"}</td></tr>)}{!shown.length && <tr><td colSpan={8} className="p-8 text-center text-gray-500">No hay gastos en esta pestaña.</td></tr>}</tbody></table></div>
    {showModal && (
      <ExpenseModal providers={providers} onClose={() => setShowModal(false)} onCreated={() => { setShowModal(false); setReloadKey((current) => current + 1); }} />
    )}
