function ExpenseModal({ providers, onClose, onCreated }: { providers: any[]; onClose: () => void; onCreated: () => void }) {
  const [form, setForm] = useState(emptyExpense);
  const [providerFilter, setProviderFilter] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === "Escape" && !saving) onClose(); }; window.addEventListener("keydown", close); return () => window.removeEventListener("keydown", close); }, [onClose, saving]);
  const date = `${form.day}/${form.month}/${form.year}`;
  const valid = Boolean(form.id_proveedor && /^\d{2}\/\d{2}\/\d{4}$/.test(date) && Number(form.total_pago) > 0);
  const save = async () => { try { setSaving(true); setError(""); const response = await fetch("/api/v1/direccion/prevision-gastos", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...form, fecha_pago: date }) }); const data = await response.json(); if (!response.ok) throw new Error(data.message); onCreated(); } catch (requestError: any) { setError(requestError.message || "No se ha podido crear el gasto"); setSaving(false); } };
  const shownProviders = providers.filter((provider) => !providerFilter.trim() || [provider.id_proveedor, provider.nombre_proveedor, provider.nombre_fiscal_proveedor, provider.vat_code].join(" ").toLowerCase().includes(providerFilter.trim().toLowerCase())).slice(0, 10);
  return <div role="dialog" aria-modal="true" aria-labelledby="expense-modal-title" className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget && !saving) onClose(); }}><section className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-xl bg-white shadow-2xl"><header className="flex justify-between border-b px-6 py-4"><div><h2 id="expense-modal-title" className="text-xl font-semibold text-blue-950">Agregar gasto previsto</h2><p className="text-sm text-gray-500">Registra un pago. Si hay varios vencimientos, crea un registro para cada uno.</p></div><button type="button" onClick={onClose} disabled={saving} aria-label="Cerrar" className="flex h-9 w-9 cursor-pointer items-center justify-center rounded-full border text-2xl transition hover:bg-gray-100 disabled:cursor-not-allowed">×</button></header><div className="space-y-4 p-6">
    <SearchableSelect label="Proveedor" value={form.id_proveedor} onChange={id=>setForm({...form,id_proveedor:id})} options={providers.map(p=>({value:p.id_proveedor,label:p.nombre_proveedor||p.nombre_fiscal_proveedor||p.id_proveedor,searchText:JSON.stringify(p)}))} />
    <div className="grid gap-4 sm:grid-cols-2"><label className="text-sm font-medium">Nombre o concepto<input value={form.nombre_planificacion} onChange={(e) => setForm({ ...form, nombre_planificacion: e.target.value })} className="mt-1 w-full rounded border px-3 py-2"/></label><label className="text-sm font-medium">Nº factura de proveedor (opcional)<input value={form.id_factura_proveedor} onChange={(e) => setForm({ ...form, id_factura_proveedor: e.target.value })} className="mt-1 w-full rounded border px-3 py-2"/></label></div>
    <fieldset><legend className="mb-1 text-sm font-medium">Fecha prevista del pago</legend><div className="flex gap-2"><input aria-label="Día" value={form.day} onChange={(e) => setForm({ ...form, day: e.target.value.replace(/\D/g, "").slice(0,2) })} placeholder="dd" className="w-20 rounded border px-3 py-2"/><input aria-label="Mes" value={form.month} onChange={(e) => setForm({ ...form, month: e.target.value.replace(/\D/g, "").slice(0,2) })} placeholder="mm" className="w-20 rounded border px-3 py-2"/><input aria-label="Año" value={form.year} onChange={(e) => setForm({ ...form, year: e.target.value.replace(/\D/g, "").slice(0,4) })} placeholder="yyyy" className="w-28 rounded border px-3 py-2"/></div></fieldset>
    <div className="grid gap-4 sm:grid-cols-2"><label className="text-sm font-medium">Forma<select value={form.forma_pago} onChange={(e) => setForm({ ...form, forma_pago: e.target.value })} className="mt-1 w-full cursor-pointer rounded border bg-white px-3 py-2"><option value="recibo">Recibo</option><option value="transferencia">Transferencia</option><option value="pagaré">Pagaré</option></select></label><label className="text-sm font-medium">Banco<select value={form.cuenta_pago} onChange={(e) => setForm({ ...form, cuenta_pago: e.target.value })} className="mt-1 w-full cursor-pointer rounded border bg-white px-3 py-2"><option>Sabadell</option><option>Santander</option></select></label></div>
    <div className="grid gap-4 sm:grid-cols-2"><label className="text-sm font-medium">Base imponible (€)<input type="number" min="0" step="0.01" value={form.bi_pago} onChange={(e) => setForm({ ...form, bi_pago: e.target.value })} className="mt-1 w-full rounded border px-3 py-2"/></label><label className="text-sm font-medium">Importe del pago (€)<input type="number" min="0.01" step="0.01" value={form.total_pago} onChange={(e) => setForm({ ...form, total_pago: e.target.value })} className="mt-1 w-full rounded border px-3 py-2"/></label></div>
    <label className="block text-sm font-medium">Descripción<textarea value={form.descripcion_planificacion} onChange={(e) => setForm({ ...form, descripcion_planificacion: e.target.value })} className="mt-1 min-h-20 w-full rounded border px-3 py-2"/></label>{error && <p className="rounded border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</p>}<div className="flex justify-end gap-3 border-t pt-4"><button type="button" onClick={onClose} disabled={saving} className="cursor-pointer rounded border px-4 py-2 transition hover:bg-gray-50 disabled:cursor-not-allowed">Cancelar</button><button type="button" onClick={() => void save()} disabled={!valid || saving} className="cursor-pointer rounded bg-blue-950 px-4 py-2 font-semibold text-white transition hover:bg-blue-900 disabled:cursor-not-allowed disabled:bg-gray-300">{saving ? "Guardando…" : "Crear gasto previsto"}</button></div>
  </div></section></div>;
}

"use client";
import SearchableSelect from "@/app/components/SearchableSelect";

import { useEffect, useMemo, useState } from "react";
import { CuentaService } from "@/app/service/CuentaService";
import { PrevisionIngresosService } from "@/app/service/PrevisionIngresosService";

type FormState = {
  id_cuenta: string; cliente_manual: string; tipo_ingreso: string; asociado_factura: boolean;
  numero_factura: string; day: string; month: string; year: string; forma_cobro: string; banco: string; base_imponible: string;
};

const initialForm: FormState = { id_cuenta: "", cliente_manual: "", tipo_ingreso: "recibo", asociado_factura: false, numero_factura: "", day: "", month: "", year: "", forma_cobro: "recibo", banco: "Sabadell", base_imponible: "" };

export default function AdditionalIncomeWizard({ onClose, onCreated }: { onClose: () => void; onCreated: () => void }) {
  const [step, setStep] = useState(1);
  const [withClient, setWithClient] = useState(true);
  const [form, setForm] = useState<FormState>(initialForm);
  const [accounts, setAccounts] = useState<any[]>([]);
  const [accountFilter, setAccountFilter] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => { CuentaService.getCuentas().then((data) => setAccounts(Array.isArray(data) ? data : [])).catch(() => setError("No se han podido cargar las cuentas.")); }, []);
  useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === "Escape" && !saving) onClose(); }; window.addEventListener("keydown", close); return () => window.removeEventListener("keydown", close); }, [onClose, saving]);

  const shownAccounts = useMemo(() => {
    const query = accountFilter.trim().toLowerCase();
    return accounts.filter((account) => !query || [account.id_cuenta, account.nombre_empresa, account.nombre_fiscal, account.cif, account.correo_principal].join(" ").toLowerCase().includes(query)).slice(0, 12);
  }, [accountFilter, accounts]);
  const theoreticalDate = `${form.day}/${form.month}/${form.year}`;
  const canContinue = step === 1 ? Boolean((withClient ? form.id_cuenta : form.cliente_manual.trim()) && form.tipo_ingreso)
    : step === 2 ? Boolean(!form.asociado_factura || form.numero_factura.trim())
      : step === 3 ? /^\d{2}\/\d{2}\/\d{4}$/.test(theoreticalDate)
        : step === 4 ? Boolean(form.forma_cobro) : step === 5 ? Boolean(form.banco) : Number(form.base_imponible) > 0;

  const save = async () => {
    try {
      setSaving(true); setError("");
      await PrevisionIngresosService.createIngresoAdicional({
        id_cuenta: withClient ? form.id_cuenta : "", cliente_manual: withClient ? "" : form.cliente_manual.trim(),
        tipo_ingreso: form.tipo_ingreso, asociado_factura: form.asociado_factura, numero_factura: form.numero_factura.trim(),
        fecha_teorica: theoreticalDate, forma_cobro: form.forma_cobro, banco: form.banco, base_imponible: Number(form.base_imponible),
      });
      onCreated();
    } catch (requestError: any) { setError(requestError?.response?.data?.message || "No se ha podido crear el ingreso."); setSaving(false); }
  };

  const titles = ["", "Cliente y tipo de ingreso", "Asociación con factura", "Fecha teórica", "Forma de cobro", "Banco de cobro", "Base imponible"];
  return <div role="dialog" aria-modal="true" aria-labelledby="income-wizard-title" className="fixed inset-0 z-[70] flex items-center justify-center bg-slate-950/60 p-4" onMouseDown={(event) => { if (event.target === event.currentTarget && !saving) onClose(); }}>
    <section className="max-h-[92vh] w-full max-w-3xl overflow-y-auto rounded-xl bg-white shadow-2xl">
      <header className="flex items-start justify-between border-b px-6 py-4"><div><h2 id="income-wizard-title" className="text-xl font-semibold text-blue-950">Agregar ingreso adicional sin contrato</h2><p className="mt-1 text-sm text-gray-500">{titles[step]}</p></div><button type="button" onClick={onClose} disabled={saving} aria-label="Cerrar" className="flex h-9 w-9 cursor-pointer items-center justify-center rounded-full border text-2xl transition hover:bg-gray-100 disabled:cursor-not-allowed">×</button></header>
      <div className="space-y-5 p-6">
        {step === 1 && <>
          <div className="flex items-center justify-between rounded border bg-gray-50 p-4"><div><p className="font-semibold text-gray-800">{withClient ? "Cobro asociado a cliente" : "Sin cliente asociado"}</p><p className="text-sm text-gray-500">Elige si el ingreso pertenece a una cuenta registrada.</p></div><button type="button" role="switch" aria-checked={withClient} onClick={() => { setWithClient((current) => !current); setForm((current) => ({ ...current, id_cuenta: "", cliente_manual: "" })); }} className={`relative h-7 w-14 cursor-pointer rounded-full transition ${withClient ? "bg-blue-950" : "bg-gray-400"}`}><span className={`absolute top-1 h-5 w-5 rounded-full bg-white transition ${withClient ? "left-8" : "left-1"}`} /></button></div>
          {withClient ? <SearchableSelect label="Cliente" required value={form.id_cuenta} onChange={id=>setForm(current=>({...current,id_cuenta:id}))} options={accounts.map(a=>({value:a.id_cuenta,label:[a.nombre_empresa||a.nombre_fiscal,a.id_cuenta,a.cif].filter(Boolean).join(' · '),searchText:a.correo_principal}))} /> : <label className="block text-sm font-medium">Cliente o concepto manual<input autoFocus value={form.cliente_manual} onChange={(event) => setForm({ ...form, cliente_manual: event.target.value })} className="mt-1 w-full rounded border px-3 py-2"/></label>}
          <label className="block text-sm font-medium">Tipo de ingreso<select value={form.tipo_ingreso} onChange={(event) => setForm({ ...form, tipo_ingreso: event.target.value })} className="mt-1 w-full cursor-pointer rounded border bg-white px-3 py-2"><option value="recibo">Recibo</option><option value="transferencia">Transferencia</option></select></label>
        </>}
        {step === 2 && <div className="flex items-center justify-between rounded border bg-gray-50 p-4"><div><p className="font-semibold">¿Asociado a una factura?</p><p className="text-sm text-gray-500">{form.asociado_factura ? "Sí" : "No"}</p></div><button type="button" role="switch" aria-checked={form.asociado_factura} onClick={() => setForm({ ...form, asociado_factura: !form.asociado_factura, numero_factura: "" })} className={`relative h-7 w-14 cursor-pointer rounded-full transition ${form.asociado_factura ? "bg-blue-950" : "bg-gray-400"}`}><span className={`absolute top-1 h-5 w-5 rounded-full bg-white transition ${form.asociado_factura ? "left-8" : "left-1"}`}/></button>{form.asociado_factura && <input autoFocus value={form.numero_factura} onChange={(event) => setForm({ ...form, numero_factura: event.target.value })} placeholder="Nº de factura" className="ml-4 flex-1 rounded border px-3 py-2"/>}</div>}
        {step === 3 && <fieldset><legend className="mb-2 text-sm font-medium">Fecha teórica</legend><div className="flex gap-2"><input aria-label="Día" value={form.day} onChange={(e) => setForm({ ...form, day: e.target.value.replace(/\D/g, "").slice(0, 2) })} placeholder="dd" className="w-20 rounded border px-3 py-2"/><input aria-label="Mes" value={form.month} onChange={(e) => setForm({ ...form, month: e.target.value.replace(/\D/g, "").slice(0, 2) })} placeholder="mm" className="w-20 rounded border px-3 py-2"/><input aria-label="Año" value={form.year} onChange={(e) => setForm({ ...form, year: e.target.value.replace(/\D/g, "").slice(0, 4) })} placeholder="yyyy" className="w-28 rounded border px-3 py-2"/></div></fieldset>}
        {step === 4 && <label className="block text-sm font-medium">Forma de cobro<select value={form.forma_cobro} onChange={(e) => setForm({ ...form, forma_cobro: e.target.value })} className="mt-1 w-full cursor-pointer rounded border bg-white px-3 py-2"><option value="recibo">Recibo</option><option value="transferencia">Transferencia</option><option value="pagaré">Pagaré</option><option value="tarjeta">Tarjeta</option><option value="efectivo">Efectivo</option></select></label>}
        {step === 5 && <label className="block text-sm font-medium">Banco<select value={form.banco} onChange={(e) => setForm({ ...form, banco: e.target.value })} className="mt-1 w-full cursor-pointer rounded border bg-white px-3 py-2"><option>Sabadell</option><option>Santander</option></select></label>}
        {step === 6 && <label className="block text-sm font-medium">Base imponible (€)<input type="number" min="0.01" step="0.01" value={form.base_imponible} onChange={(e) => setForm({ ...form, base_imponible: e.target.value })} className="mt-1 w-full rounded border px-3 py-2"/></label>}
        {error && <p className="rounded border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</p>}
        <footer className="flex justify-between border-t pt-5"><button type="button" disabled={step === 1 || saving} onClick={() => setStep((current) => current - 1)} className="cursor-pointer rounded border px-4 py-2 transition hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-40">Volver</button><button type="button" disabled={!canContinue || saving} onClick={() => step === 6 ? void save() : setStep((current) => current + 1)} className="cursor-pointer rounded bg-blue-950 px-4 py-2 font-semibold text-white transition hover:bg-blue-900 disabled:cursor-not-allowed disabled:bg-gray-300">{saving ? "Guardando…" : step === 6 ? "Confirmar ingreso" : "Continuar"}</button></footer>
      </div>
    </section>
  </div>;
}

'use client';
import SearchableSelect from "@/app/components/SearchableSelect";

import { useEffect, useMemo, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { BancoService } from '@/app/service/BancoService';
import { ProveedorService } from '@/app/service/ProveedorService';
import PayrollBankReview from '../PayrollBankReview';
import BankExpectedCharge from '../BankExpectedCharge';

interface LineaBanco {
  id_cargo_recurrente?: string | number | null; updated_at?: string;
  id_agente?: string; id_cuenta?: string; nombre_agente?: string; nombre_cuenta?: string; nomina_revision?: any;
  id_linea_banco: string; banco: string; fecha_operativa: string; fecha_valor: string; concepto: string;
  importe: number; saldo: number; estado_revision: boolean; comentarios: string; id_proveedor: string; nombre_proveedor: string;
}
interface Proveedor { id_proveedor: string; nombre_proveedor?: string; nombre_fiscal_proveedor?: string; }
const money = (value: number) => new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR' }).format(value);

export default function LineaBancoDetallePage() {
  const { id_linea_banco } = useParams<{ id_linea_banco: string }>();
  const router = useRouter();
  const [linea, setLinea] = useState<LineaBanco | null>(null), [proveedores, setProveedores] = useState<Proveedor[]>([]);
  const [entityType,setEntityType] = useState('proveedor');
  const [entities,setEntities] = useState<Array<{id:string;name:string}>>([]);
  const [entityError,setEntityError] = useState('');
  const [version,setVersion] = useState(0);
  const [providerFilter, setProviderFilter] = useState(''), [saving, setSaving] = useState(false), [message, setMessage] = useState(''), [error, setError] = useState('');

  useEffect(() => {
    Promise.all([BancoService.getLineaBanco(id_linea_banco), ProveedorService.getProveedores()])
      .then(([movement, providers]) => { setLinea(movement); setEntityType(movement.id_agente ? 'nomina' : movement.id_cuenta ? 'cliente' : 'proveedor'); setProveedores(Array.isArray(providers) ? providers : []); })
      .catch((e: any) => setError(e.message || 'No se pudo cargar el movimiento'));
  }, [id_linea_banco,version]);
  useEffect(() => {
    const controller = new AbortController(); setEntities([]); setEntityError('');
    const url = entityType === 'proveedor' ? '/api/v1/admin/proveedores' : entityType === 'cliente' ? '/api/v1/comercial/cuentas' : '/api/v1/direccion/laboral/empleados';
    fetch(url,{signal:controller.signal}).then(async r => { if(!r.ok) throw new Error('No se pudo cargar el listado.');return r.json(); }).then(rows => setEntities(rows.map((r:any) => entityType === 'proveedor' ? {id:r.id_proveedor,name:r.nombre_proveedor || r.nombre_fiscal_proveedor} : entityType === 'cliente' ? {id:r.id_cuenta,name:r.nombre_empresa || r.nombre_fiscal} : {id:r.id_agente,name:r.nombre || r.nombre_completo_agente}))).catch(e => {if(e.name !== 'AbortError')setEntityError(e.message)});
    return () => controller.abort();
  },[entityType]);
  const selectedId = entityType === 'nomina' ? linea?.id_agente : entityType === 'cliente' ? linea?.id_cuenta : linea?.id_proveedor;
  const shownEntities = useMemo(() => entities.filter(e => (e.id+' '+e.name).toLowerCase().includes(providerFilter.trim().toLowerCase())).slice(0,15),[entities,providerFilter]);
  const selectedProvider = proveedores.find((provider) => provider.id_proveedor === linea?.id_proveedor);
  const save = async () => {
    if (!linea) return;
    try {
      setSaving(true); setError(''); setMessage('');
      const saved = await BancoService.updateLineaBanco(linea.id_linea_banco, { estado_revision: linea.estado_revision, comentarios: linea.comentarios, id_proveedor: linea.id_proveedor || null, id_cuenta: linea.id_cuenta || null, id_agente: linea.id_agente || null });
      setLinea({ ...linea, ...saved, nombre_proveedor: selectedProvider?.nombre_proveedor || selectedProvider?.nombre_fiscal_proveedor || '' });
      setMessage('Movimiento guardado.');
    } catch (e: any) { setError(e.message || 'No se pudo guardar el movimiento'); } finally { setSaving(false); }
  };
  if (error && !linea) return <div className="p-12 text-red-700">{error}</div>;
  if (!linea) return <div className="p-12 text-gray-500">Cargando movimiento…</div>;

  return <div className="min-h-screen bg-gray-100 px-12 py-8 text-gray-800">
    <div className="mx-auto max-w-5xl">
      <div className="mb-6 flex items-center justify-between"><div><h1 className="text-2xl font-semibold">Detalle del movimiento</h1><p className="mt-1 text-sm text-gray-500">{linea.concepto}</p></div><button type="button" onClick={() => router.push('/dashboard/direccion/tesoreria')} className="cursor-pointer rounded border border-gray-300 bg-white px-4 py-2 text-sm transition hover:bg-gray-50 hover:shadow-sm">← Volver a tesorería</button></div>
      {error && <p className="mb-4 rounded border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</p>}{message && <p className="mb-4 rounded border border-green-200 bg-green-50 p-3 text-sm text-green-700">{message}</p>}
      <div className={`rounded-lg border p-6 shadow-sm ${linea.estado_revision ? 'border-green-200 bg-green-50' : 'border-gray-200 bg-white'}`}>
        <dl className="grid grid-cols-1 gap-x-8 gap-y-5 md:grid-cols-2 lg:grid-cols-3">
          <div><dt className="text-xs font-semibold uppercase text-gray-500">ID</dt><dd className="mt-1 break-all">{linea.id_linea_banco}</dd></div>
          <div><dt className="text-xs font-semibold uppercase text-gray-500">Banco</dt><dd className="mt-1">{linea.banco}</dd></div>
          <div><dt className="text-xs font-semibold uppercase text-gray-500">Estado</dt><dd className="mt-1">{linea.estado_revision ? 'Revisado' : 'Sin revisar'}</dd></div>
          <div><dt className="text-xs font-semibold uppercase text-gray-500">Fecha operativa</dt><dd className="mt-1">{linea.fecha_operativa}</dd></div>
          <div><dt className="text-xs font-semibold uppercase text-gray-500">Fecha valor</dt><dd className="mt-1">{linea.fecha_valor}</dd></div>
          <div><dt className="text-xs font-semibold uppercase text-gray-500">Importe</dt><dd className="mt-1 font-semibold">{money(linea.importe)}</dd></div>
          <div><dt className="text-xs font-semibold uppercase text-gray-500">Saldo</dt><dd className="mt-1">{money(linea.saldo)}</dd></div>
          <div className="md:col-span-2"><dt className="text-xs font-semibold uppercase text-gray-500">Concepto</dt><dd className="mt-1">{linea.concepto}</dd></div>
          <div><dt className="text-xs font-semibold uppercase text-gray-500">Destinatario</dt><dd className="mt-1">{selectedId || 'Sin asociar'}</dd></div>
          <div className="md:col-span-2"><dt className="text-xs font-semibold uppercase text-gray-500">Nombre</dt><dd className="mt-1">{entities.find(e => e.id === selectedId)?.name || linea.nombre_agente || linea.nombre_cuenta || selectedProvider?.nombre_proveedor || 'Sin asociar'}</dd></div>
        </dl>
      </div>
      <BankExpectedCharge line={linea} onSaved={() => setVersion(v => v + 1)} />
      <div className="mt-5 grid gap-5 rounded-lg bg-white p-6 shadow-sm md:grid-cols-2">
        <div><label className="block text-sm font-medium">Tipo<select value={entityType} onChange={e => { setEntityType(e.target.value); setProviderFilter(''); setLinea({...linea,id_proveedor:'',id_cuenta:'',id_agente:'',estado_revision:false,nomina_revision:null}); }} className="mt-1 w-full cursor-pointer rounded border bg-white px-3 py-2 hover:border-blue-950"><option value="proveedor">Proveedor</option><option value="cliente">Cliente</option><option value="nomina">Nómina</option></select></label><SearchableSelect label="Asociar a" value={selectedId||''} onChange={id=>setLinea({...linea,id_proveedor:entityType==='proveedor'?id:'',id_cuenta:entityType==='cliente'?id:'',id_agente:entityType==='nomina'?id:'',estado_revision:id===selectedId?linea.estado_revision:false,nomina_revision:id===selectedId?linea.nomina_revision:null})} options={entities.map(e=>({value:e.id,label:e.name||e.id,searchText:e.id}))} />{entityError&&<p className="text-red-700">{entityError}</p>}{entityType === 'nomina' && linea.id_agente && <PayrollBankReview line={linea} employeeId={linea.id_agente} onSaved={() => setVersion(v => v + 1)} />}</div>
        <div className="space-y-4"><label className="flex cursor-pointer items-center gap-3 rounded border border-gray-200 p-3 transition hover:bg-green-50"><input type="checkbox" disabled={entityType === 'nomina'} checked={linea.estado_revision} onChange={e => setLinea({ ...linea, estado_revision: e.target.checked })} className="cursor-pointer"/><span className="text-sm font-medium">Movimiento revisado</span></label><label className="block text-sm font-medium">Comentarios<textarea value={linea.comentarios} onChange={e => setLinea({ ...linea, comentarios: e.target.value })} rows={6} className="mt-1 w-full rounded border border-gray-300 p-3 outline-none transition hover:border-blue-900 focus:border-blue-950" /></label></div>
        <div className="flex justify-end md:col-span-2"><button type="button" onClick={save} disabled={saving || (entityType === 'nomina' && !linea.estado_revision)} className="cursor-pointer rounded bg-blue-950 px-5 py-2 text-sm font-medium text-white transition hover:bg-blue-900 hover:shadow-sm disabled:cursor-not-allowed disabled:bg-gray-400">{saving ? 'Guardando…' : 'Guardar cambios'}</button></div>
      </div>
    </div>
  </div>;
}

"use client";

import React, { useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import { MediatecaService } from "@/app/service/MediatecaService";
import apiClient from '@/app/apiClient';

export type MediatecaFolder = { id: string; name: string; path: string; allowedRoles?: string[] };
const protectedRoots = new Set(['contratos_firmados','documentos_administracion','documentos_direccion','documentos_produccion']);
export type MediatecaMedia = {
  id: string;
  name: string;
  s3Key: string;
  url?: string;
  folderPath: string;
  type: "pdf" | "image";
  mimeType?: string;
};

function joinPath(segments: string[]) {
  return segments.filter(Boolean).join("/");
}

function splitPath(path?: string) {
  return String(path || "").split("/").filter(Boolean);
}

function normalizeRouteSegment(value: string) {
  return String(value || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[\s\-_–—]+/g, "_")
    .replace(/[^a-z0-9_]+/g, "")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
}

function mediaUrl(item: MediatecaMedia) {
  if (item.url) return item.url;
  const host = String(process.env.NEXT_PUBLIC_CLOUDFRONT_URL || "").replace(/^https?:\/\//, "").replace(/\/+$/, "");
  return host ? `https://${host}/${item.s3Key}` : item.s3Key;
}

function ModalFrame({ title, children, onClose }: { title: string; children: React.ReactNode; onClose: () => void }) {
  useEffect(() => { const handler=(event:KeyboardEvent)=>{if(event.key==='Escape')onClose();};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler); }, [onClose]);
  return (
    <div className="fixed inset-0 z-[80] flex items-center justify-center bg-black/40 p-4" onMouseDown={onClose}>
      <div className="w-full max-w-md rounded-lg bg-white shadow-xl" onMouseDown={(event) => event.stopPropagation()}>
        <div className="flex items-center justify-between border-b px-5 py-4">
          <h2 className="font-semibold text-gray-900">{title}</h2>
          <button type="button" onClick={onClose} aria-label="Cerrar" className="cursor-pointer rounded p-1 text-gray-500 hover:bg-gray-100">×</button>
        </div>
        <div className="p-5">{children}</div>
      </div>
    </div>
  );
}

function CreateFolderModal({ parentPath, onClose, onDone }: { parentPath: string; onClose: () => void; onDone: () => void }) {
  const [name, setName] = useState("");
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const normalizedName = normalizeRouteSegment(name);
  const displayPath = parentPath ? `${parentPath}/${normalizedName || "nueva_carpeta"}` : normalizedName || "nueva_carpeta";

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    setSaving(true);
    setError("");
    try {
      await MediatecaService.createFolder({ name, path: parentPath });
      onDone();
    } catch (err: any) {
      setError(err?.response?.data?.message || "No se ha podido crear la carpeta.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <ModalFrame title="Crear carpeta" onClose={onClose}>
      <form onSubmit={submit} className="space-y-4">
        <label className="block text-sm">
          Nombre
          <input autoFocus value={name} onChange={(event) => setName(event.target.value)} className="mt-1 w-full rounded-lg border p-2" />
        </label>
        <p className="text-xs text-gray-500">Ruta: {displayPath}</p>
        {error && <p className="text-sm text-red-700">{error}</p>}
        <div className="flex justify-end gap-2">
          <button type="button" onClick={onClose} className="rounded-lg bg-gray-100 px-4 py-2 text-sm">Cancelar</button>
          <button disabled={!name.trim() || saving} className="rounded-lg bg-blue-950 px-4 py-2 text-sm text-white disabled:opacity-50">Crear</button>
        </div>
      </form>
    </ModalFrame>
  );
}

function RenameModal({ item, onClose, onDone }: { item: MediatecaMedia; onClose: () => void; onDone: () => void }) {
  const [name, setName] = useState(item.name);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");

  async function submit(event: React.FormEvent) {
    event.preventDefault();
    setSaving(true);
    setError("");
    try {
      await MediatecaService.updateMedia(item.id, { contentName: name });
      onDone();
    } catch (err: any) {
      setError(err?.response?.data?.message || "No se ha podido renombrar el archivo.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <ModalFrame title="Renombrar archivo" onClose={onClose}>
