import React, { FC, useState } from 'react';
import F1impc from "./fasesImpCont/f1impc";
import F2impc from "./fasesImpCont/f2impc";
import F3impc from "./fasesImpCont/f3impc";

interface ImportarContactosProps {}

interface InterfazIncidencia {
  existe: boolean;
  contenido: string;
}

const ImportarContactos: FC<ImportarContactosProps> = () => {
  const [faseImportacionContacto, setFaseImportacionContacto] = useState<number>(1);
  const [configuracion, setConfiguracion] = useState<string>("");
  const [incidencias, setIncidencias] = useState<InterfazIncidencia | null>(null);

  return (
    <div className="flex flex-col bg-gray-200 h-full min-h-screen text-gray-600">
      <MiddleNav tituloprincipal="Importación de contactos" />
      <div className="bg-white mx-12 my-6 p-12 rounded-xl shadow">
        <p className='text-3xl font-bold text-blue-950 pb-12'>Importación de contactos</p>
        {faseImportacionContacto === 1 ? (
          <F1impc
            setFaseImportacionContacto={setFaseImportacionContacto}
            configuracion={configuracion}
            setConfiguracion={setConfiguracion}
          />
        ) : faseImportacionContacto === 2 ? (
          <F2impc
            setFaseImportacionContacto={setFaseImportacionContacto}
            configuracion={configuracion}
          />
        ) : (
          <F3impc setFaseImportacionContacto={setFaseImportacionContacto} incidencias={incidencias} />
        )}
      </div>
    </div>
  );
};

export default ImportarContactos;

import React, { FC, useState } from 'react';

interface f1impcProps {
  setFaseImportacionCuenta: React.Dispatch<React.SetStateAction<number>>;
  configuracion: string;
  setConfiguracion: React.Dispatch<React.SetStateAction<string>>;
}

const f1impc: FC<f1impcProps> = ({ setFaseImportacionCuenta, configuracion, setConfiguracion }) => {
  const [opcionSeleccionada, setOpcionSeleccionada] = useState<string | null>(null);

  const handleContinuar = () => {
    if (!opcionSeleccionada) {
      alert('Debe seleccionar una opción antes de continuar.');
      return;
    }

    setConfiguracion(opcionSeleccionada);

    console.log('Opción seleccionada:', opcionSeleccionada);
    setFaseImportacionCuenta(2);
  };

  return (
    <div>
      <p className='font-bold text-xl'>Fase 1/3 - Configuración de coincidencias</p>

      <p className='mt-3'>Qué desea hacer en caso de que dos id de Cuentas coincidan?</p>

      <section className='my-5 flex flex-col gap-2 my-12'>
        <label className='flex items-center gap-2 cursor-pointer'>
          <input
            type="radio"
            name="conflictoId"
            value="mantener"
            className='cursor-pointer'
            checked={opcionSeleccionada === 'mantener'}
            onChange={(e) => setOpcionSeleccionada(e.target.value)}
          />
          Mantener los datos actuales en el Cuenta, obviar nuevos datos importados
        </label>

        <label className='flex items-center gap-2 cursor-pointer'>
          <input
            type="radio"
            name="conflictoId"
            value="sustituir_todo"
            className='cursor-pointer'
            checked={opcionSeleccionada === 'sustituir_todo'}
            onChange={(e) => setOpcionSeleccionada(e.target.value)}
          />
          Sustituir todos los datos actuales del Cuenta por los nuevos importados
        </label>

        <label className='flex items-center gap-2 cursor-pointer'>
          <input
            type="radio"
            name="conflictoId"
            value="sustituir_blanco_manteniendo"
            className='cursor-pointer'
            checked={opcionSeleccionada === 'sustituir_blanco_manteniendo'}
            onChange={(e) => setOpcionSeleccionada(e.target.value)}
          />
          Sustituir únicamente los datos actualmente en blanco por los nuevos datos importados (MANTENIENDO datos en campos que estén en blanco en los datos importados)
        </label>

        <label className='flex items-center gap-2 cursor-pointer'>
          <input
            type="radio"
            name="conflictoId"
            value="sustituir_blanco_borrando"
            className='cursor-pointer'
            checked={opcionSeleccionada === 'sustituir_blanco_borrando'}
            onChange={(e) => setOpcionSeleccionada(e.target.value)}
          />
          Sustituir únicamente los datos actualmente en blanco por los nuevos datos importados (BORRANDO datos en campos que estén en blanco en los datos importados)
        </label>
      </section>

      <button
        className='bg-blue-950 hover:bg-blue-950/90 cursor-pointer text-white font-bold p-2 px-4 rounded-lg shadow-xl'
        onClick={handleContinuar}
      >
        Validar y continuar
      </button>
    </div>
  );
};

export default f1impc;

import React, { FC, useState } from 'react';

interface f2impcProps {
  setFaseImportacionCuenta: React.Dispatch<React.SetStateAction<number>>;
  configuracion: string;
}

const f2impc: FC<f2impcProps> = ({ setFaseImportacionCuenta, configuracion }) => {
  const [archivo, setArchivo] = useState<File | null>(null);
  const [error, setError] = useState<string>('');

  const handleArchivoChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setError('');
    if (!e.target.files || e.target.files.length === 0) {
      setArchivo(null);
      return;
    }

    const file = e.target.files[0];
    const extension = file.name.split('.').pop()?.toLowerCase();

    if (extension !== 'xls' && extension !== 'xlsx') {
      setError('Solo se permiten archivos Excel (.xls o .xlsx)');
      setArchivo(null);
      e.target.value = '';
      return;
    }

    setArchivo(file);
  };

  const handleContinuar = () => {
    if (!archivo) return;

    console.log('Archivo seleccionado:', archivo.name);
    setFaseImportacionCuenta(3);
  };

  const botonDisabled = !archivo || error !== '';

  return (
    <div>
      <p className='font-bold text-xl'>Fase 2/3 - Importación</p>
      <div className='flex flex-row items-center justify-between border border-gray-100 rounded-xl shadow-xl p-5 m-5'>
        <div className='flex flex-col'>
          <p className='font-bold'>Resumen de configuración actual</p>
          <p className='text-gray-400'>
            Opción seleccionada: <span className='font-bold'>{configuracion}</span>
          </p>
        </div>
        <button className='bg-gray-600 hover:bg-gray-600/90 cursor-pointer rounded-xl shadow-xl text-white text-sm px-3 p-2  '
        onClick={()=>{setFaseImportacionCuenta(1)}}>Modificar</button>
      </div>

      <div className='my-12'>
        <label className='block font-semibold mb-2'>Seleccione un archivo Excel:</label>
        <div className="relative w-full max-w-sm">
          <input
            type="file"
            accept=".xls,.xlsx"
            onChange={handleArchivoChange}
            id="archivo"
            className="hidden"
          />
          <label
            htmlFor="archivo"
            className="flex items-center justify-between border p-2 rounded-md cursor-pointer bg-white hover:bg-gray-100"
          >
            <span>{archivo ? archivo.name : "Selecciona un archivo"}</span>
            <span className="ml-2 bg-blue-500 text-white px-3 py-1 rounded-md text-sm">Subir</span>
          </label>
        </div>

        {error && <p className='mt-2 text-red-600'>{error}</p>}
        {archivo && !error && <p className='mt-2 text-green-600'>Archivo listo: {archivo.name}</p>}
      </div>

      <button
        className={`bg-blue-950 text-white font-bold p-2 px-4 rounded-lg shadow-xl
          ${botonDisabled ? 'cursor-not-allowed bg-blue-950/50' : 'hover:bg-blue-950/90 cursor-pointer'}`}
        onClick={handleContinuar}
        disabled={botonDisabled}
      >
        Validar y continuar
      </button>
    </div>
  );
};

export default f2impc;

